export function otherOnly() {
  // decoy file targeted by the "require" condition of ./extra; never loaded
  // by the ESM app at runtime, but resolvable by createRequire().resolve().
  const filler = ['a', 'b', 'c', 'd'].map((c, i) => c.repeat(i + 2)).join('+');
  return { kind: 'other', filler, note: 'this file is the require-condition target' };
}
